        assert exc.value.lexer_value == '-'
        assert "Unknown token" in exc.value.message

    def test_minus_followed_by_non_digit_raises(self):
        with pytest.raises(LexerError) as exc:
            list(Lexer().tokenize('-a'))
        assert exc.value.lexer_value == '-'
        assert "Unknown token" in exc.value.message


# ---------------------------------------------------------------- brackets

class TestBrackets:
    def test_lbracket(self):
