            ('flatten', '[]'),
            ('unquoted_identifier', 'foo'),
            ('eof', ''),
        ]

    def test_filter_then_more(self):
        assert toks('[?a') == [
            ('filter', '[?'),
            ('unquoted_identifier', 'a'),
            ('eof', ''),
        ]

    def test_lbracket_then_content(self):
