            ('number', 2),
            ('rbracket', ']'),
            ('eof', ''),
        ]

    def test_negative_number(self):
        tokens = tokenize('-5')
        assert tokens[0] == {'type': 'number', 'value': -5,
                             'start': 0, 'end': 2}

    def test_negative_multi_digit(self):
