class TestLiteral:
    def test_json_string(self):
        tokens = tokenize('`"foo"`')
        assert tokens[0]['type'] == 'literal'
        assert tokens[0]['value'] == 'foo'

    def test_json_number(self):
        tokens = tokenize('`42`')
        assert tokens[0]['type'] == 'literal'
        assert tokens[0]['value'] == 42

    def test_json_object(self):
        tokens = tokenize('`{"a": 1}`')
        assert tokens[0]['type'] == 'literal'
